public void solve() {    
    int n = in.nextInt(), m = in.nextInt();
    Floyd_Warshall fw = new Floyd_Warshall(n);
    for (int i = 0; i < m; i++) {
        int u = in.nextInt(), v = in.nextInt();
        long w = in.nextLong();
        --u; --v;
        fw.addEdge(u, v, w);
    }
    fw.run();
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < (1 << n); i++) 
        for (int j = 0; j < n; j++) 
            dp[i][j] = Long.MAX_VALUE;
    for (int i = 0; i < n; i++) 
        dp[1 << i][i] = 0;
    for (int i = 0; i < (1 << n); i++) {
        for (int j = 0; j < n; j++) 
            if (((i >> j) & 1) == 1) {
                if (dp[i][j] == Long.MAX_VALUE) continue;
                for (int k = 0; k < n; k++) 
                    if (((i >> k) & 1) == 0 && fw.dist(j, k) != Long.MAX_VALUE) {
                        dp[i | (1 << k)][k] = Math.min(dp[i | (1 << k)][k], dp[i][j] + fw.dist(j, k));
                    }
            }
    }
    long min = Long.MAX_VALUE;
    for (int i = 0; i < n; i++) 
        min = Math.min(min, dp[(1 << n) - 1][i]);
    out.println(min == Long.MAX_VALUE ? no : min);
}
